export type AudioCategory = 'music' | 'sfx' | 'ui' | 'ambient';

export interface AudioEventDefinition {
  id: string;
  url: string;
  category: AudioCategory;
  volume?: number;
  loop?: boolean;
  optional?: boolean;
}

export interface AudioPlaybackOptions {
  category: AudioCategory;
  volume: number;
  loop: boolean;
}

export interface AudioBackend {
  load(url: string): Promise<AudioBuffer>;
  play(buffer: AudioBuffer, options: AudioPlaybackOptions): void;
  stopAll?(): void;
  dispose?(): void;
}

export interface AudioLoadResult {
  id: string;
  loaded: boolean;
  fallback: boolean;
  error?: unknown;
}

export interface AudioLoadProgress {
  completed: number;
  total: number;
  ratio: number;
  currentId?: string;
}

export type AudioProgressListener = (progress: AudioLoadProgress) => void;

class WebAudioBackend implements AudioBackend {
  private readonly context: AudioContext;

  constructor(context?: AudioContext) {
    const AudioContextCtor = globalThis.AudioContext;
    if (!context && !AudioContextCtor) throw new Error('Web Audio API is not available');
    this.context = context ?? new AudioContextCtor();
  }

  async load(url: string): Promise<AudioBuffer> {
    const response = await fetch(url);
    if (!response.ok) throw new Error(`Audio request failed: ${response.status} ${response.statusText}`);
    const data = await response.arrayBuffer();
    return this.context.decodeAudioData(data.slice(0));
  }

  play(buffer: AudioBuffer, options: AudioPlaybackOptions): void {
    const source = this.context.createBufferSource();
    const gain = this.context.createGain();
    source.buffer = buffer;
    source.loop = options.loop;
    gain.gain.value = options.volume;
    source.connect(gain);
    gain.connect(this.context.destination);
    source.start();
  }

  dispose(): void {
    void this.context.close();
  }
}

interface StoredAudioEvent {
  definition: AudioEventDefinition;
  buffer?: AudioBuffer;
}

const DEFAULT_CATEGORY_VOLUMES: Record<AudioCategory, number> = {
  music: 0.7,
  sfx: 1,
  ui: 0.9,
  ambient: 0.8,
};

function clampVolume(value: number): number {
  return Math.min(1, Math.max(0, value));
}

export class AudioManager {
  private readonly events = new Map<string, StoredAudioEvent>();
  private readonly categoryVolumes: Record<AudioCategory, number> = { ...DEFAULT_CATEGORY_VOLUMES };
  private masterVolume = 1;
  private muted = false;

  constructor(private readonly backend: AudioBackend = new WebAudioBackend()) {}

  register(definition: AudioEventDefinition): void {
    this.events.set(definition.id, { definition });
  }

  registerMany(definitions: readonly AudioEventDefinition[]): void {
    for (const definition of definitions) this.register(definition);
  }

  async loadEvent(id: string): Promise<AudioLoadResult> {
    const event = this.events.get(id);
    if (!event) throw new Error(`Unknown audio event: ${id}`);
    try {
      event.buffer = await this.backend.load(event.definition.url);
      return { id, loaded: true, fallback: false };
    } catch (error) {
      if (event.definition.optional === false) throw error;
      event.buffer = undefined;
      return { id, loaded: false, fallback: true, error };
    }
  }

  async loadAll(onProgress?: AudioProgressListener): Promise<readonly AudioLoadResult[]> {
    const ids = [...this.events.keys()];
    const total = ids.length;
    if (total === 0) {
      onProgress?.({ completed: 0, total: 0, ratio: 1 });
      return [];
    }
    let completed = 0;
    const results: AudioLoadResult[] = [];
    onProgress?.({ completed, total, ratio: 0 });
    for (const id of ids) {
      results.push(await this.loadEvent(id));
      completed += 1;
      onProgress?.({ completed, total, ratio: completed / total, currentId: id });
    }
    return results;
  }

  play(id: string): boolean {
    const event = this.events.get(id);
    if (!event?.buffer || this.muted) return false;
    const volume = clampVolume(this.masterVolume * this.categoryVolumes[event.definition.category] * clampVolume(event.definition.volume ?? 1));
    if (volume <= 0) return false;
    this.backend.play(event.buffer, { category: event.definition.category, volume, loop: event.definition.loop ?? false });
    return true;
  }

  setMasterVolume(volume: number): void { this.masterVolume = clampVolume(volume); }
  getMasterVolume(): number { return this.masterVolume; }
  setCategoryVolume(category: AudioCategory, volume: number): void { this.categoryVolumes[category] = clampVolume(volume); }
  getCategoryVolume(category: AudioCategory): number { return this.categoryVolumes[category]; }
  setMuted(muted: boolean): void { this.muted = muted; }
  isMuted(): boolean { return this.muted; }
  stopAll(): void { this.backend.stopAll?.(); }

  dispose(): void {
    this.stopAll();
    this.events.clear();
    this.backend.dispose?.();
  }
}
